@layer components {
  :where([data-control-family="tabs"][data-slot="root"]) {
    --tabs-trigger-radius: var(--radius-control);
    --tabs-list-padding: 0.25rem;
    --tabs-list-radius: calc(var(--_tabs-trigger-radius-fit) + var(--_tabs-list-radius-offset));
    --tabs-list-background: oklch(from var(--foreground) l c h / 0.07);
    --tabs-list-backdrop-filter: none;
    --tabs-indicator-background: var(--background);
    --tabs-active-foreground: var(--foreground);
    --tabs-indicator-shadow: var(--shadow-sm);
    --tabs-trigger-focus-shadow: 0 0 0 2px var(--focus-ring, oklch(from var(--foreground) l c h / 0.2));
    --tabs-line-border-color: var(--border);
    --tabs-line-indicator-background: var(--foreground);
  }
  :where([data-control-family="tabs"][data-slot="list"]) {
    --_tabs-trigger-radius-fit: min(var(--tabs-trigger-radius), calc(var(--_tabs-trigger-h) / 2));
    --_tabs-list-radius-offset: clamp(0px, calc(var(--_tabs-trigger-radius-fit) * 1000), var(--tabs-list-padding));
    --_tabs-list-h: calc(var(--_tabs-trigger-h) + var(--tabs-list-padding) + var(--tabs-list-padding));
    position: relative;
    display: flex;
    min-height: var(--_tabs-list-h);
    width: fit-content;
    align-items: center;
    gap: 0.25rem;
    border-radius: var(--tabs-list-radius);
    background: var(--tabs-list-background);
    box-shadow: inset 0 0 0 1px oklch(from var(--foreground) l c h / 0.06);
    padding: var(--tabs-list-padding);
    -webkit-backdrop-filter: var(--tabs-list-backdrop-filter);
    backdrop-filter: var(--tabs-list-backdrop-filter);
  }

  :where([data-control-family="tabs"][data-slot="indicator"]) {
    position: absolute;
    top: 50%;
    left: 0;
    z-index: 0;
    height: var(--_tabs-trigger-h);
    width: var(--active-tab-width);
    transform: translateX(var(--active-tab-left)) translateY(-50%);
    border-radius: var(--_tabs-trigger-radius-fit);
    background: var(--tabs-indicator-background);
    box-shadow: var(--tabs-indicator-shadow);
    transition:
      width var(--duration-base) var(--ease-standard),
      transform var(--duration-base) var(--ease-standard),
      background-color var(--duration-fast) var(--ease-standard),
      box-shadow var(--duration-fast) var(--ease-standard);
  }

  :where([data-control-family="tabs"][data-slot="tab"]) {
    position: relative;
    z-index: 1;
    display: inline-flex;
    height: var(--_tabs-trigger-h);
    flex-shrink: 0;
    cursor: pointer;
    align-items: center;
    justify-content: center;
    gap: 0.375rem;
    white-space: nowrap;
    border-radius: var(--_tabs-trigger-radius-fit);
    padding-inline: 0.875rem;
    color: var(--muted-foreground);
    font-size: var(--text-label);
    font-weight: 500;
    outline: none;
    transition: color var(--duration-fast) var(--ease-standard);
  }

  :where([data-control-family="tabs"][data-slot="tab"]:hover) {
    color: var(--foreground);
  }

  :where([data-control-family="tabs"][data-slot="tab"]:is([aria-selected="true"], [data-active])) {
    color: var(--tabs-active-foreground);
  }

  :where([data-control-family="tabs"][data-slot="tab"]:focus-visible) {
    box-shadow: var(--tabs-trigger-focus-shadow);
  }

  :where([data-control-family="tabs"][data-slot="tab"][data-disabled]) {
    cursor: not-allowed;
    opacity: 0.5;
  }

  :where([data-control-family="tabs"][data-slot="list"][data-variant="browser"]) {
    --_tabs-browser-corner-double: calc(var(--_tabs-trigger-radius-fit) + var(--_tabs-trigger-radius-fit));
    min-height: calc(var(--_tabs-trigger-h) + var(--tabs-list-padding));
    align-items: flex-end;
    isolation: isolate;
    border-radius: var(--tabs-list-radius) var(--tabs-list-radius) 0 0;
    box-shadow: inset 0 -1px 0 var(--tabs-line-border-color);
  }

  :where([data-control-family="tabs"][data-slot="list"][data-variant="browser"] [data-slot="indicator"]) {
    --_tabs-browser-indicator-width: calc(var(--active-tab-width) + var(--_tabs-browser-corner-double));
    --_tabs-browser-indicator-x: calc(var(--active-tab-left) - var(--_tabs-trigger-radius-fit));
    -webkit-mask:
      radial-gradient(circle closest-side, oklch(0 0 0) calc(100% - 0.5px), transparent 100%) left var(--_tabs-trigger-radius-fit) top /
        var(--_tabs-browser-corner-double) var(--_tabs-browser-corner-double) no-repeat,
      radial-gradient(circle closest-side, oklch(0 0 0) calc(100% - 0.5px), transparent 100%) right var(--_tabs-trigger-radius-fit) top /
        var(--_tabs-browser-corner-double) var(--_tabs-browser-corner-double) no-repeat,
      linear-gradient(oklch(0 0 0) 0 0) center top /
        calc(100% - var(--_tabs-browser-corner-double) - var(--_tabs-browser-corner-double)) var(--_tabs-trigger-radius-fit) no-repeat,
      linear-gradient(oklch(0 0 0) 0 0) center bottom / calc(100% - var(--_tabs-browser-corner-double))
        calc(100% - var(--_tabs-trigger-radius-fit)) no-repeat,
      radial-gradient(circle var(--_tabs-trigger-radius-fit) at top left, transparent calc(100% - 0.5px), oklch(0 0 0) 100%) left bottom /
        var(--_tabs-trigger-radius-fit) var(--_tabs-trigger-radius-fit) no-repeat,
      radial-gradient(circle var(--_tabs-trigger-radius-fit) at top right, transparent calc(100% - 0.5px), oklch(0 0 0) 100%) right bottom /
        var(--_tabs-trigger-radius-fit) var(--_tabs-trigger-radius-fit) no-repeat;
    mask:
      radial-gradient(circle closest-side, oklch(0 0 0) calc(100% - 0.5px), transparent 100%) left var(--_tabs-trigger-radius-fit) top /
        var(--_tabs-browser-corner-double) var(--_tabs-browser-corner-double) no-repeat,
      radial-gradient(circle closest-side, oklch(0 0 0) calc(100% - 0.5px), transparent 100%) right var(--_tabs-trigger-radius-fit) top /
        var(--_tabs-browser-corner-double) var(--_tabs-browser-corner-double) no-repeat,
      linear-gradient(oklch(0 0 0) 0 0) center top /
        calc(100% - var(--_tabs-browser-corner-double) - var(--_tabs-browser-corner-double)) var(--_tabs-trigger-radius-fit) no-repeat,
      linear-gradient(oklch(0 0 0) 0 0) center bottom / calc(100% - var(--_tabs-browser-corner-double))
        calc(100% - var(--_tabs-trigger-radius-fit)) no-repeat,
      radial-gradient(circle var(--_tabs-trigger-radius-fit) at top left, transparent calc(100% - 0.5px), oklch(0 0 0) 100%) left bottom /
        var(--_tabs-trigger-radius-fit) var(--_tabs-trigger-radius-fit) no-repeat,
      radial-gradient(circle var(--_tabs-trigger-radius-fit) at top right, transparent calc(100% - 0.5px), oklch(0 0 0) 100%) right bottom /
        var(--_tabs-trigger-radius-fit) var(--_tabs-trigger-radius-fit) no-repeat;
  }

  :where([data-tabs="line"] [data-control-family="tabs"][data-slot="root"]) {
    --tabs-list-padding: 0px;
  }

  :where([data-tabs="line"] [data-control-family="tabs"][data-slot="list"]) {
    min-height: var(--_tabs-trigger-h);
    width: 100%;
    gap: 0;
    border-radius: 0;
    border-block-end: 1px solid var(--tabs-line-border-color);
    background: transparent;
    padding: 0;
    -webkit-backdrop-filter: none;
    backdrop-filter: none;
  }

  :where([data-tabs="line"] [data-control-family="tabs"][data-slot="indicator"]) {
    top: auto;
    bottom: 0;
    height: 2px;
    transform: translateX(var(--active-tab-left));
    border-radius: 9999px;
    background: var(--tabs-line-indicator-background);
    box-shadow: none;
  }

  :where([data-tabs="line"] [data-control-family="tabs"][data-slot="tab"]) {
    border-radius: 0;
    padding-inline: 1rem;
  }

  :where([data-control-family="tabs"][data-slot="list"][data-single="true"]) {
    min-height: auto;
    gap: 0;
    border-radius: 0;
    background: transparent;
    padding: 0;
  }

  :where([data-control-family="tabs"][data-slot="list"][data-single="true"] [data-slot="tab"]) {
    height: auto;
    cursor: default;
    border-radius: 0;
    padding-inline: 0;
    color: var(--muted-foreground);
  }

  :where([data-control-family="tabs"][data-slot="panel"]) {
    --_tabs-panel-outline: none;
    outline-style: var(--_tabs-panel-outline);
  }

  :where([data-control-family="tabs"][data-slot="panel"]:focus-visible) {
    box-shadow: 0 0 0 2px var(--focus-ring,oklch(from var(--foreground) l c h / 0.2));
  }

  :where([data-control-family="tabs"][data-slot="tab"]:is(:where(.group\/tabs-list)[data-variant="browser"] *)) {
    border-top-left-radius: var(--_tabs-trigger-radius-fit);
    border-top-right-radius: var(--_tabs-trigger-radius-fit);
    border-bottom-right-radius: 0;
    border-bottom-left-radius: 0;
  }

  :where([data-control-family="tabs"][data-slot="list"][data-variant="browser"]) {
    border-bottom-right-radius: 0;
    border-bottom-left-radius: 0;
  }

  :where([data-control-family="tabs"][data-slot="list"][data-variant="browser"] [data-slot="indicator"]) {
    border-radius: 0px;
  }
}

